// DOM 构建完成后再查询元素（或给 script 加 defer）
document.addEventListener("DOMContentLoaded", () => {
  const list = document.querySelector("#todo-list");
  const items = ["买牛奶", "<img src=x onerror=alert(1)>"];

  // 批量插入：先放进 DocumentFragment，只触发一次插入
  const frag = document.createDocumentFragment();
  for (const text of items) {
    const li = document.createElement("li");
    li.textContent = text; // 用 textContent，不解析 HTML，防 XSS
    frag.append(li);
  }
  list.append(frag);

  // 事件委托：一个监听器处理所有 li，包括后来新增的
  list.addEventListener("click", (e) => {
    const li = e.target.closest("li");
    if (li) li.classList.toggle("done");
  });
});

// Button.tsx：基础组件，只关心外观与点击
type ButtonProps = {
  variant?: "primary" | "ghost";
  onClick?: () => void;
  children: React.ReactNode; // 组合：内容由外部决定
};

export function Button({ variant = "primary", onClick, children }: ButtonProps) {
  return (
    <button className={`btn btn-${variant}`} onClick={onClick}>
      {children}
    </button>
  );
}

// Counter.tsx：业务组件，持有状态，组合基础组件
import { useState } from "react";

export function Counter() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <span>已点击 {count} 次</span>
      <Button onClick={() => setCount((c) => c + 1)}>+1</Button>
    </div>
  );
}

// localStorage 只存字符串，对象需序列化；读写都可能抛错
function savePrefs(prefs) {
  try {
    localStorage.setItem("prefs:v1", JSON.stringify(prefs));
  } catch (e) {
    console.warn("存储失败（配额满或被禁用）", e);
  }
}

function loadPrefs() {
  try {
    return JSON.parse(localStorage.getItem("prefs:v1")) ?? { theme: "light" };
  } catch {
    return { theme: "light" }; // 数据损坏时回退默认值
  }
}

// 其他标签页修改时同步界面
window.addEventListener("storage", (e) => {
  if (e.key === "prefs:v1") applyTheme(loadPrefs().theme);
});

